"""Filesystem crawling and snapshot creation, implemented using POSIX metadata."""
import os
import stat
import pwd
import fnmatch
import time
import signal
import resource
from common import *


def segfault():
    resource.setrlimit(resource.RLIMIT_CORE, (0,0))
    os.kill(os.getpid(), signal.SIGSEGV)


def run_index(opts, paths):
    uid = 0
    if 'username' in opts:
        try: uid = pwd.getpwnam(opts['username']).pw_uid
        except (KeyError, TypeError): segfault()
    elif 'uid' in opts:
        uid = atoi(opts['uid'])
        try: pwd.getpwuid(uid)
        except (KeyError, OverflowError): segfault()
    verbose = opts.get('verbose') or opts.get('debug')
    quiet = opts.get('quiet') and not verbose
    debug = opts.get('debug')
    for path in paths:
        try:
            vfs = os.statvfs(path)
        except OSError:
            err("Can't run statvfs on %s" % path)
            return 1
        if verbose:
            err('Found big filesystem')
    if opts.get('_default_db'):
        try: os.makedirs(os.path.dirname(opts['database']), exist_ok=True)
        except OSError: pass
    db = open_db(opts, 'index', True)
    if db is None: return 1
    buckets = max(0, min(4096, atoi(opts.get('buckets'), 48)))
    maxdepth = atoi(opts.get('max-depth'), 0)
    top_count = max(0, min(1000000, atoi(opts.get('topn'), 10)))
    seen = set()
    patterns = opts.get('exclude', [])
    working_dir = os.getcwd()
    for input_path in paths:
        root = canonical(input_path, working_dir)
        root_dev = None
        try: root_dev = os.stat(root).st_dev
        except OSError: pass
        meta = {'path':root, 'date':time.time(), 'files':0, 'dirs':0, 'app':0, 'act':0, 'hist':[0]*buckets}
        top = []
        def warn(msg):
            if not quiet: err(msg)
        def crawl(path, name, depth, isroot=False):
            try:
                st = os.stat(path) if isroot else os.lstat(path)
            except OSError as ex:
                warn('Error statting %s: %s' % (path, ex.strerror))
                return None
            if not stat.S_ISDIR(st.st_mode):
                if isroot:
                    warn('skipping %s: Not a directory' % path)
                    return None
                tp = kind(st.st_mode)
                app = st.st_size
                act = st.st_blocks*512
                if opts.get('check-hard-links') and st.st_nlink > 1:
                    ident = (st.st_dev, st.st_ino)
                    if ident in seen: return None
                    seen.add(ident)
                meta['files'] += 1
                bucket = max(0, app.bit_length()-1)
                if bucket < buckets:
                    meta['hist'][bucket] += 1
                else:
                    warn('File sizes large enough we ran out of histogram buckets %d, please increase the number of buckets and re-run your indexing.' % buckets)
                if app > 10240:
                    top.append({'path':path, 'app':app})
                if debug:
                    err('  %s %d %d %s' % (classify({'type':tp}),app,act,name))
                return {'name':'<FILE>' if opts.get('hide-file-names') else name, 'type':tp, 'app':app, 'act':act, 'count':1}
            meta['dirs'] += 1
            ent = {'name':name, 'type':'dir', 'app':0, 'act':st.st_blocks*512, 'count':1, 'ref':path}
            if debug: err('>> ' + name)
            try:
                with os.scandir(path) as iterator:
                    names = [e.name for e in iterator]
            except OSError as ex:
                warn('skipping %s: %s' % (path, ex.strerror))
                return None
            entries = []
            for childname in names:
                childpath = path.rstrip('/') + '/' + childname
                if any(fnmatch.fnmatchcase(childname, p) for p in patterns):
                    warn('skipping %s: Excluded by user' % childpath)
                    continue
                try:
                    childstat = os.lstat(childpath)
                except OSError as ex:
                    warn('Error statting %s: %s' % (childpath, ex.strerror))
                    continue
                if uid and childstat.st_uid != uid: continue
                if opts.get('one-file-system') and stat.S_ISDIR(childstat.st_mode) and childstat.st_dev != root_dev:
                    continue
                child = crawl(childpath, childname, depth+1)
                if child is None: continue
                for field in ('app','act','count'): ent[field] += child[field]
                if not maxdepth or depth < maxdepth:
                    if child['type'] != 'dir' or not maxdepth or depth+1 < maxdepth:
                        entries.append(child)
            if not opts.get('dry-run') and (isroot or not maxdepth or depth < maxdepth):
                db.data['nodes'][path] = entries
            if debug: err('<< %s actual:%d apparent:%d' % (name, ent['app'], ent['act']))
            return ent
        rootent = crawl(root, root, 0, True)
        if rootent:
            meta['app'],meta['act'] = rootent['app'],rootent['act']
        if not opts.get('dry-run'):
            roots = db.data['roots']
            idx = next((i for i,r in enumerate(roots) if r['path']==root), None)
            if idx is None: roots.append(meta)
            else: roots[idx] = meta
            top.sort(key=lambda e:-e['app'])
            # The largest-file summary is collected for the current crawl.
            db.data['top'] = top[:top_count]
            db.save()
        if opts.get('progress'):
            sys.stdout.write('\x1b[K[#-------] Indexed %sb in %d files and %d directories\r\n' % (sizefmt(meta['act'],opts.get('bytes')),meta['files'],meta['dirs']))
        if verbose:
            err('Indexed %d files and %d directories, (%sB apparent, %sB actual) in 0.00 secs.' % (meta['files'],meta['dirs'],sizefmt(meta['app'],opts.get('bytes')),sizefmt(meta['act'],opts.get('bytes'))))
        if rootent:
            working_dir = os.path.dirname(os.path.realpath(root)) or '/'
    db.close()
    return 0
