"""Shared representations and formatting for the disk-usage tools."""
import os
import re
import sys
import stat
import json
import sqlite3
import math
import unicodedata

VERSION = 'duc version: 1.5.0-rc1\noptions: cairo x11 ui sqlite3\n'


def err(s):
    sys.stderr.write(s + ('\n' if not s.endswith('\n') else ''))


def atoi(s, default=0):
    if s is None:
        return default
    m = re.match(r'\s*([+-]?\d+)', str(s))
    return int(m.group(1)) if m else 0


def atof(s, default=0.0):
    if s is None:
        return default
    m = re.match(r'\s*([+-]?(?:\d+(?:\.\d*)?|\.\d+)(?:[eE][+-]?\d+)?)', str(s))
    if m:
        return float(m.group(1))
    if str(s).lower().startswith('nan'):
        return float('nan')
    if str(s).lower().startswith('inf'):
        return float('inf')
    return 0.0


def sizefmt(n, exact=False):
    if exact or n < 1024:
        return str(int(n))
    unit = 0
    v = float(n)
    while v >= 1024 and unit < 6:
        v /= 1024.0
        unit += 1
    return '%.1f%s' % (v, ' KMGTPE'[unit])


def width(s):
    return sum(0 if unicodedata.combining(c) else 2 if unicodedata.east_asian_width(c) in ('W', 'F') else 1 for c in s)


def align(s, w):
    return s + ' ' * max(0, w-width(s))


def sort_entries(entries, opts):
    if opts.get('name-sort'):
        key = lambda e: os.fsencode(e['name'])
    elif opts.get('count'):
        key = lambda e: (-e['count'], os.fsencode(e['name']))
    elif opts.get('apparent'):
        key = lambda e: (-e['app'], -e['act'], os.fsencode(e['name']))
    else:
        key = lambda e: (-e['act'], -e['app'], os.fsencode(e['name']))
    return sorted(entries, key=key)


def measure(e, opts):
    return e['count'] if opts.get('count') else e['app'] if opts.get('apparent') else e['act']


def totals(entries):
    return {k:sum(e[k] for e in entries) for k in ('app','act','count')}


def classify(e):
    return {'dir':'/', 'link':'>', 'fifo':'|', 'socket':'=', 'block':'#', 'char':'%'} .get(e['type'], ' ')


def kind(mode):
    if stat.S_ISDIR(mode): return 'dir'
    if stat.S_ISLNK(mode): return 'link'
    if stat.S_ISFIFO(mode): return 'fifo'
    if stat.S_ISSOCK(mode): return 'socket'
    if stat.S_ISBLK(mode): return 'block'
    if stat.S_ISCHR(mode): return 'char'
    return 'file'


def canonical(p, cwd=None):
    if not os.path.isabs(p):
        p = os.path.join(cwd or os.getcwd(), p)
    return os.path.normpath(p).replace('//','/')


class Database:
    """An independent, persistent collection of directory snapshots.

    A node stores its immediate entries; aggregate counters on directory entries
    deliberately remain snapshots, even if that child is indexed separately.
    """
    def __init__(self, path, write=False):
        self.path = path
        self.connection = None
        self.data = {'roots': [], 'nodes': {}, 'top': []}
        self.error = None
        try:
            exists = os.path.exists(path)
            if not path:
                self.error = 'No error: success'
            elif os.path.isdir(path) or (not write and not exists):
                self.error = 'Database not found'
            elif not write and os.path.getsize(path) == 0:
                self.error = 'No error: success'
            else:
                if not write:
                    uri = 'file:' + __import__('urllib.parse', fromlist=['quote']).quote(os.path.abspath(path)) + '?mode=ro'
                    self.connection = sqlite3.connect(uri, uri=True)
                else:
                    self.connection = sqlite3.connect(path)
                tables = self.connection.execute("SELECT name FROM sqlite_master WHERE type='table'").fetchall()
                if ('disk_usage_snapshot',) in tables:
                    r = self.connection.execute('SELECT content FROM disk_usage_snapshot WHERE id=1').fetchone()
                    if r:
                        self.data = json.loads(r[0])
                elif tables or (exists and os.path.getsize(path) > 0):
                    self.error = 'No error: success'
                elif write:
                    self.connection.execute('CREATE TABLE disk_usage_snapshot (id INTEGER PRIMARY KEY, content TEXT NOT NULL)')
                    self.connection.commit()
                else:
                    self.error = 'No error: success'
        except sqlite3.DatabaseError as ex:
            self.error = 'Database not found' if 'open' in str(ex) or 'readonly' in str(ex) else 'Database corrupt and not usable'
        except (OSError, ValueError, TypeError):
            self.error = 'Database corrupt and not usable'

    def save(self):
        if self.connection and not self.error:
            blob = json.dumps(self.data, ensure_ascii=True, separators=(',',':'))
            try:
                self.connection.execute('INSERT OR REPLACE INTO disk_usage_snapshot VALUES(1,?)', (blob,))
                self.connection.commit()
            except sqlite3.Error:
                pass

    def close(self):
        if self.connection:
            self.connection.close()

    def entries(self, path):
        return self.data['nodes'].get(path)

    def lookup(self, path, report=True):
        path = canonical(path)
        # Only scanned roots and directories reached through an indexed entry
        # are navigable.  An arbitrary file is not a directory query.
        roots = [r['path'] for r in self.data['roots'] if path == r['path'] or path.startswith(r['path'].rstrip('/') + '/')]
        if not roots:
            if report:
                err('Path %s not found in database' % path)
            return None
        for root in sorted(roots, key=len, reverse=True):
            current = root
            entries = self.entries(current)
            if entries is None:
                continue
            suffix = path[len(root):].strip('/')
            good = True
            if suffix:
                for name in suffix.split('/'):
                    ent = next((e for e in entries if e['name'] == name and e['type']=='dir'), None)
                    if ent is None:
                        good = False
                        break
                    current = ent['ref']
                    entries = self.entries(current)
                    if entries is None:
                        good = False
                        break
            if good:
                return current, entries
        return None


def open_db(opts, cmd, write=False):
    path = opts['database']
    if opts.get('verbose') or opts.get('debug'):
        err('%s database "%s"' % ('Writing to' if write else 'Reading from', path))
    db = Database(path, write)
    if db.error:
        if db.error == 'No error: success':
            err('Error opening: %s - unsupported DB type _unknown_, duc compiled for sqlite3' % path)
        else:
            err('Error opening: %s - %s' % (path, db.error))
        if cmd not in ('ls','ui','gui'):
            err(db.error)
        db.close()
        return None
    return db


def query_path(db, path, cmd):
    result = db.lookup(path)
    if result is None:
        if cmd in ('ls','ui','gui'):
            err("The requested path '%s' was not found in the database,\nPlease run 'duc info' for a list of available directories." % path)
        else:
            err('Requested path not found')
    return result
