"""Text, XML and JSON views of indexed directory snapshots."""
import os
import sys
import time
from common import *


def run_info(db, opts):
    print('Date       Time       Files    Dirs    Size Path')
    for root in db.data['roots']:
        date = time.strftime('%Y-%m-%d %H:%M:%S', time.localtime(root['date']))
        sz = root['app'] if opts.get('apparent') else root['act']
        print('%s %7s %7s %7s %s' % (date, sizefmt(root['files'],opts.get('bytes')), sizefmt(root['dirs'],opts.get('bytes')),sizefmt(sz,opts.get('bytes')),root['path']))
        if opts.get('histogram'):
            print('\nHistogram:\n----------')
            for i,count in enumerate(root['hist']):
                if count: print('2^%-3d %d' % (i,count))
    return 0


def run_histogram(db,opts):
    for root in db.data['roots']:
        print('Path: ' + root['path'])
        print('Bkt       Size      Count')
        for i,n in enumerate(root['hist']):
            print('%3d %10s %10d' % (i, sizefmt(1 << i,opts.get('bytes')),n))
        print()
    return 0


def run_topn(db,opts):
    print('        Size Filename')
    for ent in db.data.get('top',[]):
        print('%12s %s' % (sizefmt(ent['app'],opts.get('bytes')),ent['path']))
    return 0


def ls_color(ent):
    return {'dir':'\x1b[1;34m', 'link':'\x1b[1;36m','fifo':'\x1b[33m','socket':'\x1b[1;35m'}.get(ent['type'],'')


def run_ls(db,opts,paths):
    exact = opts.get('bytes')
    szwidth = 12 if exact else 6
    levels = atoi(opts.get('levels'),4)
    is_tty = sys.stdout.isatty()
    try: columns = os.get_terminal_size(sys.stdout.fileno()).columns
    except OSError: columns = 80
    recursive = opts.get('recursive')
    full = opts.get('full-path')
    ascii_tree = opts.get('ascii')
    connector = ['`+- ', ' |- ', ' `- '] if ascii_tree else ['╰┬─ ', ' ├─ ', ' ╰─ ']
    stem = ' |  ' if ascii_tree else ' │  '
    def listing(entries, depth, treeprefix='', pathprefix=''):
        if depth > levels: return
        entries = sort_entries(entries, opts)
        maxname = max((width(e['name']) for e in entries),default=0) + (1 if opts.get('classify') else 0)
        maxvalue = max((measure(e,opts) for e in entries),default=0)
        first = True
        for i,e in enumerate(entries):
            last = i == len(entries)-1
            if opts.get('dirs-only') and e['type'] != 'dir': continue
            s = sizefmt(measure(e,opts),exact)
            name = e['name']
            if opts.get('classify'): name += classify(e)
            prefix = ''
            if recursive and not full:
                prefix = treeprefix + connector[2 if last else 0 if first else 1]
            if full:
                name = pathprefix + name
            if is_tty and opts.get('color'):
                color = ls_color(e)
                if color: name = color + name + '\x1b[0m'
            text = '%*s %s%s' % (szwidth,s,prefix,name)
            if opts.get('graph') and not full:
                bars = max(0, columns - szwidth - 9 - maxname - depth*4)
                n = int(measure(e,opts)*bars/maxvalue) if maxvalue else 0
                text += ' ' * max(0,maxname-width(e['name'])-(1 if opts.get('classify') else 0))
                text += ' [' + '+'*n + ' '*(bars-n) + ']'
            print(text)
            first = False
            if recursive and e['type']=='dir':
                child = db.entries(e['ref'])
                if child is not None:
                    listing(child,depth+1,treeprefix+('    ' if last else stem),pathprefix+e['name']+'/')
    for path in paths or ['.']:
        found = query_path(db,path,'ls')
        if found is None: return 1
        _,entries=found
        if opts.get('directory'):
            sz = sizefmt(measure(totals(entries),opts),exact)
            print('%s %s%s' % (sz,path,'/' if opts.get('classify') else ''))
        else:
            listing(entries,0)
    return 0


def xml_escape(s):
    return s.replace('&','&amp;').replace('<','&lt;').replace('>','&gt;').replace('"','&quot;')


def run_export(db,opts,path,format):
    found = query_path(db,path,format)
    if found is None: return 1
    _, entries = found
    root = totals(entries)
    field = 'app' if opts.get('apparent') else 'act'
    minimum = atoi(opts.get('min_size'))
    def include(e):
        return e[field] >= minimum and (not opts.get('exclude-files') or e['type']=='dir')
    if format == 'xml':
        print('<?xml version="1.0" encoding="UTF-8"?>')
        print('<duc root="%s" size_apparent="%d" size_actual="%d" count="%d">' % (path,root['app'],root['act'],root['count']))
        def write_xml(entries,depth):
            for e in sort_entries(entries,{}):
                if not include(e): continue
                pad = ' '*depth
                name = xml_escape(e['name'])
                if e['type']=='dir':
                    print('%s<ent type="dir" name="%s" size_apparent="%d" size_actual="%d" count="%d">' % (pad,name,e['app'],e['act'],e['count']))
                    write_xml(db.entries(e['ref']) or [],depth+1)
                    print(pad+'</ent>')
                else:
                    print('%s<ent name="%s" size_apparent="%d" size_actual="%d" />' % (pad,name,e['app'],e['act']))
        write_xml(entries,1)
        print('</duc>')
    else:
        def obj(name,e,entries,depth):
            p = ' '*depth
            lines = [p+'{',p+'  "name": "'+name+'",']
            if entries is not None: lines.append(p+'  "count": %d,' % e['count'])
            lines.append(p+'  "size_apparent": %d,' % e['app'])
            lines.append(p+'  "size_actual": %d%s' % (e['act'],',' if entries is not None else ''))
            if entries is not None:
                lines.append(p+'  "children": [')
                kids=[]
                for child in sort_entries(entries,{}):
                    if include(child):
                        kids.append(obj(child['name'],child,(db.entries(child['ref']) or []) if child['type']=='dir' else None,depth+4))
                    else: kids.append('')
                lines.append(',\n'.join(kids))
                lines.append(p+'  ]')
