"""Command line entry point for the independent disk usage implementation."""
import os
import sys
import re
import json
import pkgutil
from common import *
from indexer import run_index, segfault
from queries import run_ls, run_info, run_topn, run_histogram, run_export

HELP = json.loads(pkgutil.get_data('app','help_text.json').decode())
COMMANDS = [c for c in HELP if not c.startswith('_')]


def specifications(cmd):
    spec = []
    for line in HELP[cmd].splitlines():
        match = re.match(r'\s+(?:-(.),\s+)?--([\w-]+)(=VAL)?\s+',line)
        if match:
            short, long, arg = match.groups()
            spec.append((short,long,bool(arg)))
    return spec


def set_option(opts,key,value=None):
    if key == 'exclude':
        opts.setdefault(key,[]).append(value)
    else:
        opts[key] = True if value is None else value


def parse_args(args,spec,opts):
    byshort={s:(l,a) for s,l,a in spec if s}
    bylong={l:a for s,l,a in spec}
    rest=[]
    i=0
    def bad(message):
        err(sys.argv[0]+': '+message)
        err("Try 'duc --help' for more information.")
        return None
    while i < len(args):
        arg=args[i];i+=1
        if arg=='--': rest.extend(args[i:]);break
        if not arg.startswith('-') or arg=='-':
            rest.append(arg)
            if os.environ.get('POSIXLY_CORRECT'):
                rest.extend(args[i:]);break
            continue
        if arg.startswith('--'):
            text=arg[2:];name,eq,value=text.partition('=')
            matches=[k for k in bylong if k.startswith(name)]
            if name in bylong: chosen=name
            elif len(matches)==1: chosen=matches[0]
            elif len(matches)>1:
                return bad("option '%s' is ambiguous; possibilities: %s" % (arg,' '.join("'--%s'" % m for m in matches)))
            else: return bad("unrecognized option '%s'" % arg)
            if bylong[chosen]:
                if not eq:
                    if i==len(args): return bad("option '%s' requires an argument" % arg)
                    value=args[i];i+=1
                set_option(opts,chosen,value)
            else:
                if eq: return bad("option '--%s' doesn't allow an argument" % name)
                set_option(opts,chosen)
        else:
            j=1
            while j<len(arg):
                short=arg[j];j+=1
                if short not in byshort: return bad("invalid option -- '%s'" % short)
                long,needarg=byshort[short]
                if needarg:
                    if j<len(arg): value=arg[j:];j=len(arg)
                    elif i<len(args): value=args[i];i+=1
                    else: return bad("option requires an argument -- '%s'" % short)
                    set_option(opts,long,value)
                    break
                set_option(opts,long)
    return rest


def read_configs(cmd,spec,opts):
    options={l:a for s,l,a in spec}
    home=os.environ.get('HOME','')
    config=os.environ.get('XDG_CONFIG_HOME',os.path.join(home,'.config'))
    for filename in ['/etc/ducrc',os.path.join(config,'duc','ducrc'),os.path.join(home,'.ducrc'),os.path.join(os.getcwd(),'.ducrc')]:
        try:
            f=open(filename,encoding='utf-8',errors='surrogateescape')
        except OSError: continue
        section='global'
        with f:
            for line in f:
                line=line.strip()
                if not line or line.startswith('#'): continue
                if line.startswith('['):
                    section=line[1:].split(']',1)[0]
                    continue
                if section not in ('global',cmd): continue
                fields=line.split(None,1)
                name=fields[0]
                if name not in options:
                    err("Unknown option '%s'" % name)
                    continue
                if options[name]:
                    if len(fields)==1: segfault()
                    set_option(opts,name,fields[1])
                else: set_option(opts,name)


def select_database(opts):
    if 'database' in opts:
        return
    home=os.environ.get('HOME','')
    old=os.path.join(home,'.duc.db')
    if os.path.exists(old):
        if not opts.get('quiet') or opts.get('verbose') or opts.get('debug'):
            err('Using old database at "%s", please move this to "$XDG_CACHE_HOME/duc/duc.db"' % old)
        opts['database']=old
    else:
        cache=os.environ.get('XDG_CACHE_HOME',os.path.join(home,'.cache'))
        opts['database']=os.path.join(cache,'duc','duc.db')
        opts['_default_db']=True


def main():
    # Preserve raw file names through both the POSIX interface and text output.
    try:
        sys.stdout.reconfigure(errors='surrogateescape')
        sys.stderr.reconfigure(errors='surrogateescape')
    except AttributeError: pass
    args=sys.argv[1:]
    first=args[0] if args else 'help'
    cmd=first if first in COMMANDS else 'help'
    opts={}
    if 'DUC_DATABASE' in os.environ: opts['database']=os.environ['DUC_DATABASE']
    spec=specifications(cmd)
    read_configs(cmd,spec,opts)
    if first=='--version': opts['version']=True
    paths=parse_args(args[1:],spec,opts)
    if paths is None: return 1
    if opts.get('version'):
        sys.stdout.write(VERSION);return 0
    if opts.get('help') and cmd != 'help':
        sys.stdout.write(HELP[cmd]);return 0
    if cmd=='help':
        if paths and paths[0] in COMMANDS: text=HELP[paths[0]]
        elif opts.get('all'): text=HELP['_all']
        else: text=HELP['_main']
        sys.stdout.write(text);return 0
    if cmd=='index' and not paths:
        err('Required index PATH missing.')
        sys.stdout.write(HELP['index']);return 1
    if cmd=='cgi':
        from graphing import run_cgi
        select_database(opts)
        return run_cgi(opts,paths)
    select_database(opts)
    if cmd=='index': return run_index(opts,paths)
    db=open_db(opts,cmd)
    if db is None: return 1
    try:
        if cmd=='info': return run_info(db,opts)
        if cmd=='histogram': return run_histogram(db,opts)
        if cmd=='topn': return run_topn(db,opts)
        if cmd=='ls': return run_ls(db,opts,paths)
        if cmd in ('xml','json'): return run_export(db,opts,paths[0] if paths else '.',cmd)
        if cmd=='graph':
            from graphing import run_graph
            return run_graph(db,opts,paths[0] if paths else '.')
        if cmd in ('gui','ui'):
            path=paths[0] if paths else '.'
            found=query_path(db,path,cmd)
            if found is None:return 1
            if cmd=='gui':
                err('ERROR: Could not open display');return 1
            from terminal import run_ui
            return run_ui(db,opts,path,found)
    finally: db.close()
    return 0


if __name__=='__main__':
    raise SystemExit(main())
