    def color(self,norm,fraction,depth,a1,a2):
        palette=self.opts.get('palette','size')
        light=0
        saturation=1-.8*depth/self.levels if self.levels else float('nan')
        if palette=='monochrome':
            return (1,1,1),.01
        if palette=='greyscale':
